import 'package:dio/dio.dart';import 'package:flutter/widgets.dart';import 'package:zan/Core/Storage/Remote/api_password.dart';import '../Local/local_storage_keys.dart';import '../Local/local_storage_service.dart';import 'api_endpoints.dart';import 'api_interceptor.dart';class DioHelper {  static late Dio dio;  static void init(String state) {    dio = Dio(      BaseOptions(        baseUrl: ApiEndpoints.baseUrl,        receiveDataWhenStatusError: true,        connectTimeout: const Duration(seconds: 10),        receiveTimeout: const Duration(seconds: 10),        headers: {          'Content-Type': 'application/json',        },        queryParameters: {          'api_password': ApiPassword.password,        },      ),    );    dio.interceptors.add(ApiInterceptor());    dio.interceptors.add(      LogInterceptor(        request: true,        // requestHeader: true,        // requestBody: true,        // responseHeader: true,        // responseBody: true,        // error: true,      ),    );  }  /// Handles GET requests  static Future<Response?> getData({    required String path,    Map<String, dynamic>? queryParameters,  }) async {    try {      return await dio.get(        path,        queryParameters: queryParameters,        options: await _getAuthorizationHeader(),      );    } catch (e) {      debugPrint('❌ GET Error: $e');      return null;    }  }  /// Handles POST requests  static Future<Response?> postData({    required String path,    required dynamic data,    Map<String, dynamic>? queryParameters,  }) async {    try {      return await dio.post(        path,        data: data,        queryParameters: queryParameters,        options: await _getAuthorizationHeader(),      );    } catch (e) {      debugPrint('❌ POST Error: $e');      return null;    }  }  /// Handles PUT requests  static Future<Response?> putData({    required String path,    required Map<String, dynamic> data,    Map<String, dynamic>? queryParameters,  }) async {    try {      return await dio.put(        path,        data: data,        queryParameters: queryParameters,        options: await _getAuthorizationHeader(),      );    } catch (e) {      debugPrint('❌ PUT Error: $e');      return null;    }  }  /// Handles DELETE requests  static Future<Response?> deleteData({    required String path,    Map<String, dynamic>? queryParameters,  }) async {    try {      return await dio.delete(        path,        queryParameters: queryParameters,        options: await _getAuthorizationHeader(),      );    } catch (e) {      debugPrint('❌ DELETE Error: $e');      return null;    }  }  static Future<Options> _getAuthorizationHeader() async {    String? token = LocalStorageService.getValue(LocalStorageKeys.token);    return Options(      headers: {        'Authorization': token != null && token.isNotEmpty ? 'bearer $token' : '',      },    );  }}